-- ACTUALIZACION DE prueba.lineas_unificadas (RMA + Productos/Test)
-- Procedencia: volcados del 17-11-2026 proporcionados por el usuario.
-- Fuente RMA: 7.711 filas; fuente Productos/Test: 6.983 filas.
-- NO borra, reemplaza ni modifica registros anteriores de lineas_unificadas.
-- NO necesita que existan lineas_rma ni linea_test_productos en el ordenador de destino.
-- IMPORTANTE: hacer copia de seguridad de prueba antes de ejecutar.
-- Requiere que prueba.lineas_unificadas tenga la estructura facilitada, y
-- que prueba.tipo_registro admita los valores 3 y 6.
-- En la primera ejecucion agrega las filas que no tengan su ID de origen.
-- Si ya existen IDs de origen, las omite (no actualiza sus valores).

USE `prueba`;
SET NAMES utf8mb4;

-- Las tablas temporales son independientes de las tablas originales.
DROP TEMPORARY TABLE IF EXISTS `_import_rma_20261117`;
DROP TEMPORARY TABLE IF EXISTS `_import_test_20261117`;
CREATE TEMPORARY TABLE `_import_rma_20261117` (
  `idLineas_rma` bigint(20) NOT NULL,
  `NPedido` int(11) NOT NULL,
  `rma` varchar(30) NOT NULL,
  `CMMF` varchar(20) NOT NULL,
  `referencia` varchar(40) NOT NULL,
  `descripcion` varchar(200) NOT NULL,
  `woPortugal` varchar(50) NOT NULL,
  `mr` varchar(5) NOT NULL,
  `alarma` varchar(100) NOT NULL,
  `facturado` varchar(20) NOT NULL,
  `motivoRechazo` varchar(200) NOT NULL,
  `udPedido` int(11) NOT NULL,
  `udAnuladas` int(11) NOT NULL,
  `udAlbaran` int(11) NOT NULL,
  `codFamilia` int(11) NOT NULL,
  `subCodFamilia` varchar(8) NOT NULL,
  `descripcionMarca` varchar(100) NOT NULL,
  `llegada` varchar(10) NOT NULL,
  `codBarrasSeb` varchar(15) NOT NULL,
  `noAbono` varchar(50) NOT NULL,
  `movChManual` varchar(100) NOT NULL,
  `fechaMovChManual` date DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=UTF8MB4;
CREATE TEMPORARY TABLE `_import_test_20261117` (
  `idTest_linea` bigint(20) NOT NULL,
  `rma` varchar(30) NOT NULL,
  `CMMF` varchar(20) NOT NULL,
  `referenciaProductoTest` varchar(40) NOT NULL,
  `idFamilia` int(11) NOT NULL,
  `fechaCompra` varchar(10) NOT NULL,
  `fechaFabricacion` varchar(10) NOT NULL,
  `garantia` varchar(20) NOT NULL,
  `codigoIris` varchar(20) NOT NULL,
  `conclusion` varchar(4) NOT NULL,
  `conclusionFinal` varchar(4) NOT NULL,
  `idPallet` bigint(20) NOT NULL,
  `idPalletPNT` bigint(20) NOT NULL,
  `observaciones` varchar(300) NOT NULL,
  `observacionesLimpieza` varchar(300) NOT NULL,
  `idUser` int(11) NOT NULL,
  `idUserLimpieza` int(11) NOT NULL,
  `tiempoTardado` varchar(30) NOT NULL,
  `diaTest` varchar(20) NOT NULL,
  `fechaTest` date DEFAULT NULL,
  `horaInicioTest` time NOT NULL,
  `horaTest` time NOT NULL,
  `fechaLimpieza` date NOT NULL DEFAULT '1111-11-11',
  `horaInicioLimpieza` time NOT NULL,
  `horaFinLimpieza` time NOT NULL,
  `tiempoTardadoLimpieza` time NOT NULL,
  `numOrden` int(11) NOT NULL,
  `numEntrada` int(11) NOT NULL,
  `punteado` int(11) NOT NULL,
  `tipoEnvio` varchar(1) NOT NULL,
  `agora` varchar(1) NOT NULL DEFAULT 'N'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Carga de datos históricos SOLO en tablas temporales:

-- Comprobacion de integridad de los datos recibidos (resultado esperado: 7711 y 6983)
SELECT (SELECT COUNT(*) FROM `_import_rma_20261117`) AS filas_rma_fuente,
       (SELECT COUNT(*) FROM `_import_test_20261117`) AS filas_test_fuente;

START TRANSACTION;

-- En el destino se genera idLineaUnificada automaticamente.
    `tipoRegistro`, `idLineas_rma`, `NPedido`, `rma`, `CMMF`, `referencia`, `descripcion`, `woPortugal`, `mr`, `alarma`, `facturado`, `motivoRechazo`, `udPedido`, `udAnuladas`, `udAlbaran`, `codFamilia`, `subCodFamilia`, `descripcionMarca`, `llegada`, `codBarrasSeb`, `noAbono`, `movChManual`, `fechaMovChManual`
)
SELECT
    3, src.`idLineas_rma`, src.`NPedido`, src.`rma`, src.`CMMF`, src.`referencia`, src.`descripcion`, src.`woPortugal`, src.`mr`, src.`alarma`, src.`facturado`, src.`motivoRechazo`, src.`udPedido`, src.`udAnuladas`, src.`udAlbaran`, src.`codFamilia`, src.`subCodFamilia`, src.`descripcionMarca`, src.`llegada`, src.`codBarrasSeb`, src.`noAbono`, src.`movChManual`, src.`fechaMovChManual`
FROM `_import_rma_20261117` AS src
WHERE NOT EXISTS (
    SELECT 1 FROM `lineas_unificadas` AS destino
    WHERE destino.`idLineas_rma` = src.`idLineas_rma`
);

SELECT ROW_COUNT() AS rma_insertados_en_esta_ejecucion;

    `tipoRegistro`, `idTest_linea`, `rma`, `CMMF`, `referenciaProductoTest`, `idFamilia`, `fechaCompra`, `fechaFabricacion`, `garantia`, `codigoIris`, `conclusion`, `conclusionFinal`, `idPallet`, `idPalletPNT`, `observaciones`, `observacionesLimpieza`, `idUser`, `idUserLimpieza`, `tiempoTardado`, `diaTest`, `fechaTest`, `horaInicioTest`, `horaTest`, `fechaLimpieza`, `horaInicioLimpieza`, `horaFinLimpieza`, `tiempoTardadoLimpieza`, `numOrden`, `numEntrada`, `punteado`, `tipoEnvio`, `agora`
)
SELECT
    6, src.`idTest_linea`, src.`rma`, src.`CMMF`, src.`referenciaProductoTest`, src.`idFamilia`, src.`fechaCompra`, src.`fechaFabricacion`, src.`garantia`, src.`codigoIris`, src.`conclusion`, src.`conclusionFinal`, src.`idPallet`, src.`idPalletPNT`, src.`observaciones`, src.`observacionesLimpieza`, src.`idUser`, src.`idUserLimpieza`, src.`tiempoTardado`, src.`diaTest`, src.`fechaTest`, src.`horaInicioTest`, src.`horaTest`, src.`fechaLimpieza`, src.`horaInicioLimpieza`, src.`horaFinLimpieza`, src.`tiempoTardadoLimpieza`, src.`numOrden`, src.`numEntrada`, src.`punteado`, src.`tipoEnvio`, src.`agora`
FROM `_import_test_20261117` AS src
WHERE NOT EXISTS (
    SELECT 1 FROM `lineas_unificadas` AS destino
    WHERE destino.`idTest_linea` = src.`idTest_linea`
);

SELECT ROW_COUNT() AS test_insertados_en_esta_ejecucion;

-- Cantidades de los codigos del volcado ya presentes en lineas_unificadas.
SELECT
  (SELECT COUNT(*) FROM `_import_rma_20261117` r
     JOIN `lineas_unificadas` u ON u.idLineas_rma=r.idLineas_rma
     WHERE u.tipoRegistro=3) AS rma_presentes,
  (SELECT COUNT(*) FROM `_import_test_20261117` t
     JOIN `lineas_unificadas` u ON u.idTest_linea=t.idTest_linea
     WHERE u.tipoRegistro=6) AS test_presentes;

COMMIT;

DROP TEMPORARY TABLE IF EXISTS `_import_rma_20261117`;
DROP TEMPORARY TABLE IF EXISTS `_import_test_20261117`;

-- Resultado esperado de la comprobacion final: 7711 RMA y 6983 test,
-- suponiendo que ninguno de estos ID haya cambiado de tipo por datos previos.
